class Solution {
    public int countPalindromicSubsequence(String s) {
        int answer = 0;
        for (int outer = 0; outer < 26; outer++) {
            char ch = (char) ('a' + outer);
            int first = s.indexOf(ch);
            int last = s.lastIndexOf(ch);
            if (first == -1 || first == last) {
                continue;
            }

            boolean[] middleSeen = new boolean[26];
            int distinctMiddle = 0;
            for (int i = first + 1; i < last; i++) {
                int middle = s.charAt(i) - 'a';
                if (!middleSeen[middle]) {
                    middleSeen[middle] = true;
                    distinctMiddle++;
                }
            }
            answer += distinctMiddle;
        }
        return answer;
    }
}

class Solution {
    public int countPalindromicSubsequence(String s) {
        int n = s.length();
        boolean[][] left = new boolean[n][26];
        boolean[][] right = new boolean[n][26];

        for (int i = 1; i < n; i++) {
            System.arraycopy(left[i - 1], 0, left[i], 0, 26);
            left[i][s.charAt(i - 1) - 'a'] = true;
        }
        for (int i = n - 2; i >= 0; i--) {
            System.arraycopy(right[i + 1], 0, right[i], 0, 26);
            right[i][s.charAt(i + 1) - 'a'] = true;
        }

        boolean[][] counted = new boolean[26][26];
        int answer = 0;
        for (int middleIndex = 0; middleIndex < n; middleIndex++) {
            int middle = s.charAt(middleIndex) - 'a';
            for (int outer = 0; outer < 26; outer++) {
                if (left[middleIndex][outer] && right[middleIndex][outer] && !counted[outer][middle]) {
                    counted[outer][middle] = true;
                    answer++;
                }
            }
        }
        return answer;
    }
}

class Solution {
    public int countPalindromicSubsequence(String s) {
        int[] rightCount = new int[26];
        int rightMask = 0;
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            rightCount[c]++;
            rightMask |= 1 << c;
        }

        int leftMask = 0;
        boolean[][] counted = new boolean[26][26];
        int answer = 0;
        for (int i = 0; i < s.length(); i++) {
            int middle = s.charAt(i) - 'a';
            rightCount[middle]--;
            if (rightCount[middle] == 0) {
                rightMask &= ~(1 << middle);
            }

            int outerMask = leftMask & rightMask;
            while (outerMask != 0) {
                int bit = outerMask & -outerMask;
                int outer = Integer.numberOfTrailingZeros(bit);
                if (!counted[outer][middle]) {
                    counted[outer][middle] = true;
                    answer++;
                }
                outerMask -= bit;
            }

            leftMask |= 1 << middle;
        }
        return answer;
    }
}
